/* One-item exercise flow. Existing progress key and IndexedDB are retained. */
(()=>{'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),C=HanziExerciseCore.create(PRACTICE_DATA),KEY='hanzi-practice-v1';
let data=C.clean({version:1}),validLocal=false,db=null,queue=Promise.resolve(),ready=false,open=false,pendingKind=null,audio=null,playing=false,token=0,gap=null,ending=false;
try{const raw=localStorage.getItem(KEY);if(raw){data=C.clean(JSON.parse(raw));validLocal=true;}}catch{}
const nav=document.createElement('button');nav.id='nav-practise';nav.hidden=true;nav.textContent='Practise';$('header nav').insertBefore(nav,$('#nav-method'));
const section=document.createElement('section');section.id='practice-studio';section.hidden=true;section.innerHTML='<p id="practice-save" role="status"></p><div id="practice-body"></div>';$('#workspace').after(section);
function status(text){$('#practice-save').textContent=text;}
function save(){const snapshot=JSON.stringify(data);let local=false;try{localStorage.setItem(KEY,snapshot);local=true;}catch{}status('Saving…');queue=queue.catch(()=>{}).then(()=>new Promise(resolve=>{if(!db){status(local?'Saved on this device':'Saving unavailable. Export a backup before leaving.');resolve();return;}try{const tx=db.transaction('progress','readwrite');tx.objectStore('progress').put(JSON.parse(snapshot),'practice');tx.oncomplete=()=>{status('Saved on this device');resolve();};tx.onerror=tx.onabort=()=>{status(local?'Saved in browser storage':'Saving unavailable. Export a backup.');resolve();};}catch{status(local?'Saved in browser storage':'Saving unavailable. Export a backup.');resolve();}}));return queue;}
function remember(){try{localStorage.setItem('hanzi-practice-open',String(open));}catch{}}
function stop(){token++;if(gap)clearTimeout(gap);gap=null;if(audio){audio.pause();audio.onended=null;audio.onerror=null;audio=null;}playing=false;}
function show(){open=true;section.hidden=false;$('#workspace').hidden=true;$('.intro').hidden=true;$('#nav-read').classList.remove('active');remember();}
function close(){pendingKind=null;open=false;stop();section.hidden=true;$('#workspace').hidden=false;$('.intro').hidden=true;$('#nav-match').classList.remove('active');$('#nav-dictation').classList.remove('active');remember();}
function openActivity(kind){if(!['match','dictation'].includes(kind))return;window.HanziVoice?.stop();stop();ending=false;show();if(!ready){pendingKind=kind;render();return;}C.switchKind(data,kind);save();render();}
$('#nav-match').onclick=()=>openActivity('match');nav.onclick=()=>openActivity(data.kind);$('#nav-read').addEventListener('click',close);$('#lesson-list').addEventListener('click',e=>{if(e.target.closest('[data-lesson]'))close();});
const scopeName=s=>s==='all'?'All 15 lessons':s==='class'?'Lessons 9–15':'Lesson '+s;
function heading(){return `<div class="practice-heading"><div><span class="chapter-label">${data.kind==='match'?'CHARACTER PRACTICE':'PAPER DICTATION'}</span><h2>${data.kind==='match'?'Match the sound.':'Listen, then write.'}</h2><p>${data.kind==='match'?'One character at a time. Ten per round.':'Ten words. Write on paper. Check after listening.'}</p></div></div>`;}
function setup(){const pool=C.pool(data.kind,data.scope),missed=pool.filter(w=>data.stats[data.kind+':'+w.id]?.lastCorrect===false).length;return `<article class="practice-paper exercise-setup"><h3>Choose your round</h3><div class="practice-settings"><label>Vocabulary<select id="practice-scope"><option value="all">All 15 lessons</option><option value="class">Lessons 9–15</option>${BOOK.lessons.map(l=>`<option value="${l.number}">Lesson ${l.number} · ${esc(l.title)}</option>`).join('')}</select></label><label>Focus<select id="practice-filter"><option value="all">All items</option><option value="mistakes">Needs practice</option></select></label></div><p class="hint">${data.filter==='mistakes'?(missed?`${missed} missed readings available. If fewer than ten different items are missed, the round includes other vocabulary from this selection.`:'No missed items in this selection yet. Choose All items to begin.'):`${pool.length} readings available. New and due items come first.`}</p>${data.kind==='dictation'?'<p>Number your paper 1–10. Each word plays twice, slowly. The example sentence is optional. No answers appear until all ten words have been heard.</p>':'<p>Choose a pinyin, check it, then continue. The sentence shows which reading is needed.</p>'}<button id="start-practice" class="primary" ${data.filter==='mistakes'&&!missed?'disabled':''}>Start 10 ${data.kind==='match'?'characters':'words'} →</button><p id="setup-status" role="status"></p></article>`;}
function roundHead(r){const index=r.phase==='review'?r.reviewIndex:r.index;return `<div class="simple-round-heading"><span>${scopeName(r.scope)}${r.filter==='mistakes'?' · '+(r.targeted?r.targeted+' missed + '+(10-r.targeted)+' review items':'Needs practice'):''} · ${r.phase==='review'?'Check your paper':r.kind==='match'?'Character':'Word'} ${index+1} of 10</span><button id="end-round">End round</button></div>${ending?'<div class="round-end-confirm"><p>End this unfinished round without a score? Completed results stay saved.</p><button id="keep-round" class="primary">Keep this round</button><button id="confirm-end">End without scoring</button></div>':''}`;}
function context(w){const at=Number.isInteger(w.contextStart)?w.contextStart:w.context.indexOf(w.text);return at<0?esc(w.context):esc(w.context.slice(0,at))+'<mark>'+esc(w.text)+'</mark>'+esc(w.context.slice(at+w.text.length));}
function match(r){const i=r.index,w=C.banks.match.get(r.ids[i]),checked=typeof r.marks[i]==='boolean',answer=r.answers[i];return `${roundHead(r)}<article class="practice-paper simple-item"><p class="eyebrow">WHICH PINYIN MATCHES THIS CHARACTER HERE?</p><h3 id="item-heading" class="single-character" lang="zh-Hans" tabindex="-1">${esc(w.text)}</h3><p class="item-context" lang="zh-Hans">${context(w)}</p><div class="single-options" role="group" aria-label="Choose pinyin">${C.options(w.id,answer,r.created).map(p=>`<button data-pinyin="${esc(p)}" aria-pressed="${answer===p}" ${checked?'disabled':''} class="${checked&&p===w.pinyin?'correct':''} ${checked&&!r.marks[i]&&p===answer?'incorrect':''}">${esc(p)}</button>`).join('')}</div>${checked?`<div class="item-feedback" role="status"><strong>${r.marks[i]?'Correct.':'The correct reading is '+esc(w.pinyin)+'.'}</strong>${r.marks[i]?'':'<p>Read the character with its sentence once, then continue.</p>'}</div>`:'<p id="choice-status" class="hint" role="status">Choose one reading, then check it.</p>'}<div class="simple-item-actions"><button id="previous-item" ${i===0?'disabled':''}>← Previous</button>${checked?`<button id="next-item" class="primary">${i===9?'Finish round →':'Next character →'}</button>`:`<button id="check-item" class="primary" ${!answer?'disabled':''}>Check answer</button>`}</div></article>`;}
function dictation(r){if(r.phase==='review')return review(r);const i=r.index;return `${roundHead(r)}<article class="practice-paper dictation-paper simple-dictation"><span class="eyebrow">LISTEN → WRITE ON PAPER → NEXT</span><h3 id="item-heading" class="dictation-counter" tabindex="-1">${String(i+1).padStart(2,'0')}<small> / 10</small></h3><p>The word plays twice. Write its Hanzi on your paper.</p><div class="audio-actions"><button id="play-word" class="${r.heard[i]?'replay-word':'primary'}">${r.heard[i]?'↺ Replay word twice':'▶ Hear word twice'}</button><button id="play-context">Hear example sentence</button><label class="audio-speed">Speed<select id="audio-speed"><option value="0.65">Extra slow</option><option value="0.8">Slow (recommended)</option><option value="1">Original speed</option></select></label></div><div id="dictation-player" class="dictation-player"></div><p id="audio-status" role="status">${r.heard[i]?'Word heard. Write it, then continue when ready.':'Play the word before continuing. Answers stay hidden.'}</p><div class="dictation-dots" aria-label="Words heard">${r.heard.map((h,j)=>`<span class="${h?'heard':''} ${j===i?'current':''}" aria-label="Word ${j+1}${h?', heard':''}">${j+1}</span>`).join('')}</div><div class="simple-item-actions"><button id="previous-item" ${i===0?'disabled':''}>← Previous</button><button id="next-item" class="${r.heard[i]?'primary':''}" ${!r.heard[i]?'disabled':''}>${i===9?'Check my ten words →':'I’ve written it · Next →'}</button></div><p class="hint">If the sound could be more than one word, use the example sentence. It does not replace hearing the word.</p></article>`;}
function review(r){const i=r.reviewIndex,w=C.banks.dictation.get(r.ids[i]),marked=typeof r.marks[i]==='boolean';return `${roundHead(r)}<article class="practice-paper simple-item"><p class="eyebrow">NOW COMPARE WORD ${i+1} WITH YOUR PAPER</p><h3 id="item-heading" class="single-character" lang="zh-Hans" tabindex="-1">${esc(w.text)}</h3><p class="item-context" lang="zh-Hans">${context(w)}</p><p>Compare the characters and their strokes. How did you do?</p><div class="self-mark simple-self-mark" role="group" aria-label="Check your written word"><button data-self="true" aria-pressed="${r.marks[i]===true}">✓ I wrote it correctly</button><button data-self="false" aria-pressed="${r.marks[i]===false}">Needs practice</button></div><div class="simple-item-actions"><button id="previous-review" ${!i?'disabled':''}>← Previous</button><button id="next-review" class="primary" ${!marked?'disabled':''}>${i===9?'Save my ten results →':'Next answer →'}</button></div><p class="hint">This is your self-check. The site does not recognise handwriting.</p></article>`;}
function result(r){const score=Object.values(r.marks).filter(Boolean).length,missed=r.ids.filter((_,i)=>!r.marks[i]);return `<article class="practice-paper simple-result"><p class="eyebrow">ROUND COMPLETE · ${scopeName(r.scope)}</p><h3>${score}<small> / 10 ${r.kind==='dictation'?'self-marked correct':'correct'}</small></h3><p>${missed.length?`${missed.length} item${missed.length===1?'':'s'} saved as needing practice.`:'All ten correct. Try another round when ready.'}</p><div class="result-words">${r.ids.map((id,i)=>{const w=C.banks[r.kind].get(id);return `<div><strong lang="zh-Hans">${esc(w.text)}</strong>${r.kind==='match'?`<span>${esc(w.pinyin)}</span>`:''}<span>${r.marks[i]?'✓ Correct':'Needs practice'}</span></div>`;}).join('')}</div><div class="exercise-actions">${missed.length?'<button id="retry-missed" class="primary">Practise missed items →</button>':''}<button id="another-round" class="${missed.length?'':'primary'}">Another 10 →</button><button id="choose-round">Choose a lesson</button></div></article>`;}
function utilities(){return `<details class="practice-utilities"><summary>Progress & backups</summary><div class="practice-actions"><button id="practice-export">Export all progress</button><label class="import-label">Import backup<input type="file" id="practice-import" accept="application/json" hidden></label><button id="keep-storage">Protect device storage</button></div></details><details class="round-history"><summary>Recent rounds</summary><div class="practice-history">${data.history.length?`<ul>${data.history.slice(-8).reverse().map(h=>`<li>${h.kind==='match'?'Character matching':'Paper dictation'} <strong>${h.score}/10</strong><span>${new Date(h.time).toLocaleDateString()}</span></li>`).join('')}</ul>`:'<p>Your completed rounds will appear here.</p>'}</div></details>`;}
function render(focus=false){if(!ready){$('#practice-body').innerHTML='<p role="status">Loading your saved practice…</p>';return;}const r=data.round;$('#nav-match').classList.toggle('active',data.kind==='match');$('#nav-dictation').classList.toggle('active',data.kind==='dictation');section.dataset.activity=data.kind;section.dataset.round=r&&r.phase!=='complete'?'active':'ready';$('#practice-body').innerHTML=heading()+(!r?setup():r.phase==='complete'?result(r):ending?roundHead(r):r.kind==='match'?match(r):dictation(r))+utilities();bind();if(focus)$('#item-heading')?.focus({preventScroll:true});}
function begin(){stop();try{data.round=C.start(data);ending=false;save();render(true);}catch(e){$('#setup-status')?.replaceChildren(document.createTextNode(e.message));status(e.message);}}
function bind(){const r=data.round;if(!r){$('#practice-scope').value=data.scope;$('#practice-filter').value=data.filter;$('#practice-scope').onchange=e=>{data.scope=e.target.value;data.preferences[data.kind]={scope:data.scope,filter:data.filter};save();render();};$('#practice-filter').onchange=e=>{data.filter=e.target.value;data.preferences[data.kind]={scope:data.scope,filter:data.filter};save();render();};$('#start-practice').onclick=begin;}
 if($('#end-round'))$('#end-round').onclick=()=>{stop();ending=true;render();};if($('#keep-round')){$('#keep-round').onclick=()=>{ending=false;render();};$('#confirm-end').onclick=()=>{stop();data.round=null;ending=false;save();render();};}
 if(r?.kind==='match'&&r.phase==='active'){section.querySelectorAll('[data-pinyin]').forEach(b=>b.onclick=()=>{if(typeof r.marks[r.index]==='boolean')return;r.answers[r.index]=b.dataset.pinyin;save();section.querySelectorAll('[data-pinyin]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('#check-item').disabled=false;$('#choice-status').textContent='Reading selected. Check your answer.';});if($('#check-item'))$('#check-item').onclick=()=>{if(C.checkMatch(r)){save();render();}};}
 if($('#previous-item'))$('#previous-item').onclick=()=>{if(r.index>0){stop();r.index--;save();render(true);}};
 if($('#next-item'))$('#next-item').onclick=()=>{if(playing||!C.canNext(r))return;stop();if(r.index<9)r.index++;else if(r.kind==='match')C.finish(data);else C.reveal(r);save();render(true);};
 if($('#play-word')){$('#audio-speed').value=String(data.speed);$('#audio-speed').onchange=e=>{data.speed=Number(e.target.value);if(audio){audio.playbackRate=data.speed;audio.preservesPitch=true;if('webkitPreservesPitch'in audio)audio.webkitPreservesPitch=true;}save();};$('#play-word').onclick=()=>{if(playing){stop();updateAudio('Stopped. Replay when ready.');}else play(false);};$('#play-context').onclick=()=>play(true);}
 section.querySelectorAll('[data-self]').forEach(b=>b.onclick=()=>{r.marks[r.reviewIndex]=b.dataset.self==='true';save();section.querySelectorAll('[data-self]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('#next-review').disabled=false;});if($('#previous-review'))$('#previous-review').onclick=()=>{if(r.reviewIndex>0){r.reviewIndex--;save();render(true);}};if($('#next-review'))$('#next-review').onclick=()=>{if(typeof r.marks[r.reviewIndex]!=='boolean')return;if(r.reviewIndex<9)r.reviewIndex++;else C.finish(data);save();render(true);};
 if($('#another-round'))$('#another-round').onclick=()=>{data.filter='all';data.preferences[data.kind]={scope:data.scope,filter:data.filter};begin();};if($('#retry-missed'))$('#retry-missed').onclick=()=>{data.filter='mistakes';data.preferences[data.kind]={scope:data.scope,filter:data.filter};begin();};if($('#choose-round'))$('#choose-round').onclick=()=>{data.round=null;save();render();};
 $('#practice-export').onclick=()=>$('#export-progress').click();$('#practice-import').onchange=async e=>{try{await importBackup(e.target.files?.[0]);}catch{status('Could not import that backup. Choose an exported full-progress JSON file.');}e.target.value='';};$('#keep-storage').onclick=async()=>{try{const kept=await navigator.storage?.persist?.();status(kept?'Persistent storage enabled. Keep an exported backup too.':'Progress saves normally. Your browser did not grant persistent storage; keep an exported backup.');}catch{status('Persistent storage unavailable. Keep an exported backup.');}};
}
function updateAudio(message){if(!$('#play-word'))return;const heard=data.round.heard[data.round.index];$('#play-word').textContent=playing?'■ Stop audio':heard?'↺ Replay word twice':'▶ Hear word twice';$('#play-word').classList.toggle('primary',!heard);$('#play-word').classList.toggle('replay-word',heard);$('#next-item').disabled=playing||!heard;$('#next-item').classList.toggle('primary',heard&&!playing);$('#play-context').disabled=playing;if(message)$('#audio-status').textContent=message;}
async function play(contextOnly){stop();const r=data.round,i=r.index,w=C.banks.dictation.get(r.ids[i]),own=token;playing=true;updateAudio(contextOnly?'Playing an example sentence. This does not mark the word as heard.':'Listen 1 of 2…');const el=document.createElement('audio');audio=el;el.src=contextOnly?w.contextAudio:w.audio;el.preload='auto';el.playbackRate=data.speed;el.preservesPitch=true;if('webkitPreservesPitch'in el)el.webkitPreservesPitch=true;el.setAttribute('aria-label',contextOnly?'Example sentence':'Word recording');$('#dictation-player').replaceChildren(el);let repetition=1;
 const fail=()=>{if(own!==token)return;playing=false;updateAudio('Recording could not play. Press Hear word twice to retry; your place is saved.');};
 el.onerror=fail;el.onended=()=>{if(own!==token)return;if(!contextOnly&&repetition===1){repetition=2;$('#audio-status').textContent='Listen 2 of 2…';gap=setTimeout(async()=>{gap=null;if(own!==token)return;el.currentTime=0;try{await el.play();}catch{fail();}},700);return;}playing=false;if(!contextOnly){r.heard[i]=true;save();const dot=section.querySelectorAll('.dictation-dots span')[i];if(dot){dot.classList.add('heard');dot.setAttribute('aria-label','Word '+(i+1)+', heard');}updateAudio('Heard twice. Write the word, then continue when ready.');}else updateAudio(r.heard[i]?'Sentence finished. Write the word or replay it.':'Sentence finished. Play the word twice before continuing.');};try{await el.play();}catch{fail();}}
async function initialize(){try{db=await new Promise((resolve,reject)=>{const q=indexedDB.open('hanzi-reading-room',1);q.onupgradeneeded=()=>{if(!q.result.objectStoreNames.contains('progress'))q.result.createObjectStore('progress');};q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);q.onblocked=()=>reject(Error('Blocked'));});if(!validLocal){const stored=await new Promise(resolve=>{const q=db.transaction('progress').objectStore('progress').get('practice');q.onsuccess=()=>resolve(q.result);q.onerror=()=>resolve(null);});if(stored)data=C.clean(stored);}}catch{}ready=true;if(pendingKind){C.switchKind(data,pendingKind);pendingKind=null;}await save();if(open)render();}
async function importBackup(file){if(!file)return;await initialized;const raw=JSON.parse(await file.text());if(raw.format!=='hanzi-full-progress'||raw.version!==1||raw.reading?.version!==1||!raw.reading.records||!raw.reading.words)throw Error('Invalid backup');if(raw.paper&&raw.paper.version!==1)throw Error('Invalid paper backup');const imported=C.clean(raw.practice);const paper=raw.paper?window.HanziPaper?.clean(raw.paper):null;stop();if(paper)await window.HanziPaper.importData(paper);window.importReadingProgress(raw.reading);data=imported;await save();if(open)render();window.HanziPaper?.refresh();status('Backup restored on this device.');}
const initialized=initialize();window.HanziPractice={ready:initialized,snapshot:()=>JSON.parse(JSON.stringify(data)),close,openActivity,importData:async raw=>{await initialized;stop();data=C.clean(raw);await save();if(open)render();},importBackup};try{if(localStorage.getItem('hanzi-practice-open')==='true'){show();render();}}catch{}
document.addEventListener('visibilitychange',()=>{if(document.hidden&&playing){stop();updateAudio('Paused while away. Replay this word when ready.');}});
})();
